import pytest
from pricing.tiers import tier_for


def test_negative_int_raises_value_error():
    with pytest.raises(ValueError):
        tier_for(-1)


def test_negative_float_raises_value_error():
    with pytest.raises(ValueError):
        tier_for(-0.01)


def test_zero_int_returns_basic():
    assert tier_for(0) == "basic"


def test_zero_float_returns_basic():
    assert tier_for(0.0) == "basic"


def test_edge_below_100_returns_basic():
    assert tier_for(99.99) == "basic"


def test_boundary_100_int_returns_plus():
    assert tier_for(100) == "plus"


def test_boundary_100_float_returns_plus():
    assert tier_for(100.0) == "plus"


def test_midpoint_returns_plus():
    assert tier_for(500) == "plus"


def test_boundary_1000_int_returns_plus():
    assert tier_for(1000) == "plus"


def test_boundary_1000_float_returns_plus():
    assert tier_for(1000.0) == "plus"


def test_edge_above_1000_returns_pro():
    assert tier_for(1000.01) == "pro"


def test_large_amount_returns_pro():
    assert tier_for(50000) == "pro"
